import '../../core/network/api_client.dart';import '../../core/network/token_storage.dart';import '../../domain/repositories/auth_repository.dart';import '../../domain/repositories/content_repository.dart';import '../models/models.dart';
class AuthRepositoryImpl implements AuthRepository{final ApiClient client;final TokenStorage tokens;AuthRepositoryImpl(this.client,this.tokens);@override Future<UserModel?>restore()async{if(await tokens.access==null)return null;try{return UserModel.fromJson((await client.dio.get('/users/me')).data);}catch(_){await tokens.clear();return null;}}@override Future<UserModel>login(String identifier,String password)=>_auth('/auth/login',{'identifier':identifier,'password':password});@override Future<UserModel>register(String name,String identifier,String password)=>_auth('/auth/register',{'name':name,...(identifier.contains('@')?{'email':identifier}:{'phone':identifier}),'password':password});Future<UserModel>_auth(String path,Map<String,dynamic>body)async{final r=await client.dio.post(path,data:body);await tokens.save(r.data['accessToken'],r.data['refreshToken']);return UserModel.fromJson(r.data['user']);}@override Future<void>logout()async{final refresh=await tokens.refresh;try{await client.dio.post('/auth/logout',data:{'refreshToken':refresh});}finally{await tokens.clear();}}@override Future<UserModel>settings(Map<String,dynamic>data)async=>UserModel.fromJson((await client.dio.put('/users/me/settings',data:data)).data);}
class ContentRepositoryImpl implements ContentRepository{final ApiClient client;ContentRepositoryImpl(this.client);List<MovieModel>_movies(dynamic x)=>(x as List).map((e)=>MovieModel.fromJson(Map<String,dynamic>.from(e))).toList();List<ChannelModel>_channels(dynamic x)=>(x as List).map((e)=>ChannelModel.fromJson(Map<String,dynamic>.from(e))).toList();@override Future<Map<String,dynamic>>home()async{final j=Map<String,dynamic>.from((await client.dio.get('/home')).data);return{'banner':j['banner']==null?null:MovieModel.fromJson(j['banner']),'recommended':_movies(j['recommended']),'popularMovies':_movies(j['popularMovies']),'newMovies':_movies(j['newMovies']),'liveChannels':_channels(j['liveChannels']),'popularChannels':_channels(j['popularChannels']),'movieCategories':(j['movieCategories']as List).map((e)=>CategoryModel.fromJson(Map<String,dynamic>.from(e))).toList(),'tvCategories':(j['tvCategories']as List).map((e)=>CategoryModel.fromJson(Map<String,dynamic>.from(e))).toList()};}@override Future<PageResult<MovieModel>>movies({int page=1,String?category,String?sort,String?q})async{final j=(await client.dio.get('/movies',queryParameters:{'page':page,'limit':20,'category':category,'sort':sort,'q':q})).data;return PageResult(data:_movies(j['data']),page:j['meta']['page'],totalPages:j['meta']['totalPages'],hasNext:j['meta']['hasNext']);}@override Future<MovieModel>movie(String id)async=>MovieModel.fromJson((await client.dio.get('/movies/$id')).data);@override Future<PageResult<ChannelModel>>channels({int page=1,String?category,String?q})async{final j=(await client.dio.get('/channels',queryParameters:{'page':page,'limit':20,'category':category,'q':q})).data;return PageResult(data:_channels(j['data']),page:j['meta']['page'],totalPages:j['meta']['totalPages'],hasNext:j['meta']['hasNext']);}@override Future<ChannelModel>channel(String id)async=>ChannelModel.fromJson((await client.dio.get('/channels/$id')).data);@override Future<Map<String,List<dynamic>>>search(String q)async{final j=(await client.dio.get('/search',queryParameters:{'q':q})).data;return{'movies':_movies(j['movies']),'channels':_channels(j['channels'])};}@override Future<List<ProgramModel>>programs(String channelId)async{final j=(await client.dio.get('/channels/$channelId/programs')).data;return(j['programs']as List).map((e)=>ProgramModel.fromJson(Map<String,dynamic>.from(e))).toList();}@override Future<Map<String,List<dynamic>>>favorites()async{final j=(await client.dio.get('/favorites')).data;return{'movies':_movies(j['movies']),'channels':_channels(j['channels'])};}@override Future<void>favoriteMovie(String id,bool add)async{add?await client.dio.post('/favorites/movie',data:{'movieId':id}):await client.dio.delete('/favorites/movie/$id');}@override Future<void>favoriteChannel(String id,bool add)async{add?await client.dio.post('/favorites/channel',data:{'channelId':id}):await client.dio.delete('/favorites/channel/$id');}@override Future<List<MovieModel>>history()async{final j=(await client.dio.get('/history')).data;return _movies(j['data']);}@override Future<void>saveHistory(String id,int position,int duration)async{await client.dio.post('/history',data:{'movieId':id,'positionSeconds':position,'durationSeconds':duration});}@override Future<void>clearHistory()async{await client.dio.delete('/history');}}
